  options: CreateNodeCollaborationOptions,
): NodeCollaborationSessionHandle {
160→  const factory = options.createHocuspocusProvider ?? defaultHocuspocusProvider
  const handle = factory({
    url: session.url ?? '',
    name: session.room,
    token: session.token,
    document: options.doc,
