      authenticate: async () => ({ allowed: true, mode: 'rw', userId: '1' }),
      loadDocument: async (args) => {
        calls.load.push(args)
        return queue.shift()
      },
      storeDocument: async (args) => {
        calls.store.push(args)
        return store(args)
40→      },
    },
  }
}

